// Validate the webhook body and normalise it.
// Accepts: { title, date?, attendees: [{ name, email? } | "Name"], transcript? , audio_url?, clickup_list_id? }
const body = $input.first().json.body || $input.first().json;
const str = (v) => (typeof v === 'string' ? v.trim() : '');

const attendees = (Array.isArray(body.attendees) ? body.attendees : [])
  .map((a) => (typeof a === 'string' ? { name: a.trim() } : { name: str(a.name), email: str(a.email).toLowerCase() }))
  .filter((a) => a.name);

const meeting = {
  title: str(body.title) || 'Untitled meeting',
  date: /^\d{4}-\d{2}-\d{2}$/.test(str(body.date)) ? str(body.date) : $now.toISODate(),
  attendees,
  transcript: str(body.transcript),
  audio_url: str(body.audio_url),
  clickup_list_id: str(body.clickup_list_id),
};

const errors = [];
if (!meeting.transcript && !/^https:\/\//.test(meeting.audio_url)) errors.push('send a transcript or an https audio_url');
if (meeting.transcript && meeting.transcript.length < 50) errors.push('transcript is too short');
if (attendees.length === 0) errors.push('attendees are required so tasks can be assigned');
if (errors.length) throw new Error('Invalid meeting payload: ' + errors.join('; '));

return [{ json: meeting }];

// Whisper returns { text }. Merge it back into the validated meeting.
const meeting = $('Validate Input').first().json;
const text = ($input.first().json.text || '').trim();
if (!text) throw new Error('Transcription returned no text');
return [{ json: { ...meeting, transcript: text } }];

// Parse GPT's JSON, then turn each action item into a ClickUp task payload.
// ---- Configure for your workspace ----
const DEFAULT_LIST_ID = 'REPLACE_WITH_CLICKUP_LIST_ID';
// Attendee name (lower case) -> ClickUp user id. Find ids via GET /api/v2/team.
const TEAM = {
  'sara malik': 81234567,
  'omar farooq': 81234568,
  'liam smith': 81234569,
};
// --------------------------------------

const meeting = $('Validate Input').first().json;
const raw = $input.first().json.choices?.[0]?.message?.content;
let notes;
try {
  notes = JSON.parse(raw);
} catch (e) {
  throw new Error('Model did not return valid JSON: ' + String(raw).slice(0, 200));
}
for (const key of ['summary', 'decisions', 'action_items', 'risks']) {
  if (!(key in notes)) throw new Error('Model JSON is missing "' + key + '"');
}

const PRIORITY = { urgent: 1, high: 2, normal: 3, low: 4 };

// Match an owner to the team by full name, then by unique first name.
function clickupUser(owner) {
  if (!owner) return null;
  const name = owner.trim().toLowerCase();
  if (TEAM[name]) return TEAM[name];
  const first = name.split(/\s+/)[0];
  const matches = Object.keys(TEAM).filter((k) => k.split(/\s+/)[0] === first);
  return matches.length === 1 ? TEAM[matches[0]] : null;
}

function dueMs(date) {
  if (!date || !/^\d{4}-\d{2}-\d{2}$/.test(date)) return null;
  return Date.parse(date + 'T17:00:00Z');
}

const listId = meeting.clickup_list_id || DEFAULT_LIST_ID;
const items = notes.action_items
  .filter((a) => a && typeof a.task === 'string' && a.task.trim())
  .map((a) => {
    const assignee = clickupUser(a.owner);
    const due = dueMs(a.due_date);
    const task = {
      name: a.task.trim().slice(0, 200),
      description: 'From meeting "' + meeting.title + '" on ' + meeting.date + '.\n\n' +
        'Owner mentioned: ' + (a.owner || 'not assigned in the meeting') + '\n\nMeeting summary:\n' + notes.summary,
      priority: PRIORITY[a.priority] || 3,
      assignees: assignee ? [assignee] : [],
      tags: ['meeting-action'],
    };
    if (due) {
      task.due_date = due;
      task.due_date_time = false;
    }
    return { json: { list_id: listId, clickup_task: task, owner: a.owner || null, assigned: Boolean(assignee), notes } };
  });

if (items.length === 0) return [{ json: { skip: true, notes } }];
return items;

// Build the Slack recap from the notes and the tasks ClickUp created.
const parsed = $('Parse & Map Owners').all().map((i) => i.json);
const notes = parsed[0].notes;
const meeting = $('Validate Input').first().json;
const created = $input.all().map((i) => i.json).filter((t) => t && t.id && t.url);

const lines = [];
lines.push('*:memo: ' + meeting.title + '* (' + meeting.date + ')');
lines.push(notes.summary);

if (notes.decisions.length) {
  lines.push('', '*Decisions*');
  notes.decisions.forEach((d) => lines.push('• ' + d));
}

const tasks = parsed.filter((p) => !p.skip);
if (tasks.length) {
  lines.push('', '*Action items*');
  tasks.forEach((p, i) => {
    const link = created[i] ? '<' + created[i].url + '|' + p.clickup_task.name + '>' : p.clickup_task.name;
    const who = p.owner ? (p.assigned ? p.owner : p.owner + ' :warning: not in ClickUp') : ':warning: no owner';
    const due = p.clickup_task.due_date ? ' · due ' + new Date(p.clickup_task.due_date).toISOString().slice(0, 10) : '';
    lines.push('• ' + link + ' (' + who + due + ')');
  });
} else {
  lines.push('', '_No action items were agreed._');
}

if (notes.risks.length) {
  lines.push('', '*Risks / open questions*');
  notes.risks.forEach((r) => lines.push('• ' + r));
}

return [{ json: { slack_text: lines.join('\n'), tasks_created: created.length } }];
